// Package plan defines the SemanticPlan — the typed, deterministic statement of
// what a query means — and the planner that builds one from a binding.
//
// Section 4.12 of the brief: "A typed, deterministic internal object
// representing the chosen query meaning. It is not generated by an LLM."
// Section 14: the compiler turns it into SQL "without generating SQL
// free-form".
//
// A plan speaks the CONFIG's language, never SQL's: entities, fields and
// relationships by their configured names, operators and aggregations by
// their closed-vocabulary ids. It holds no table name, no column name, no SQL
// fragment. The compiler looks every name up in the registry and emits only
// what the registry holds (section 16.2), so a plan cannot smuggle an
// identifier into the output, whether it was built by the planner or written
// by hand for the Phase 6 gate.
//
// MEANING, NOT SHAPE. A plan says "customers with some order over 10000"; it
// does not say "EXISTS" or "JOIN". Which SQL construct expresses a path is the
// compiler's decision, made from configured cardinality (decision 015). The
// one semantic rule a plan author must know: a condition whose path fans out
// (reaches many rows per root row) means "SOME related row satisfies it".
//
// REDACTION (decision 006): string values are qferr.Sensitive, so a plan
// printed or marshalled by accident shows <redacted>.
package plan

import (
	"bytes"
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
	"time"

	"queryforge.local/v2experiment/internal/config"
	"queryforge.local/v2experiment/internal/numeric"
	"queryforge.local/v2experiment/internal/qferr"
)

// Plan is one query's meaning.
type Plan struct {
	// Root is the entity the query is about: one output row per root row for
	// a listing.
	Root string `json:"root"`
	// Distinct removes duplicate output rows. Listings only.
	Distinct bool `json:"distinct,omitempty"`
	// Select lists the fields to show. With aggregates, they are also what the
	// rows are grouped by.
	Select []FieldPath `json:"select,omitempty"`
	// Aggregates are the functions to compute.
	Aggregates []Aggregate `json:"aggregates,omitempty"`
	// Where restricts the root rows. Joined by WhereJoin, all the same way:
	// binding refuses a sentence that mixes "and" and "or", and a plan cannot
	// express a mix either.
	Where     []Condition `json:"where,omitempty"`
	WhereJoin Connective  `json:"whereJoin,omitempty"`
	// Having restricts groups by an aggregate's value.
	Having     []HavingCondition `json:"having,omitempty"`
	HavingJoin Connective        `json:"havingJoin,omitempty"`
	OrderBy    []OrderKey        `json:"orderBy,omitempty"`
	// Limit caps the rows. 0 means no limit.
	Limit int `json:"limit,omitempty"`
	// Notes carry structural observations from binding and planning (a unit
	// word kept but not interpreted). They are never compiled; they exist so
	// that nothing the sentence said disappears without a trace. No values.
	Notes []string `json:"notes,omitempty"`
}

// Connective joins a list of conditions. Empty means "and".
type Connective string

const (
	And Connective = "and"
	Or  Connective = "or"
)

// FieldPath is a configured field reached from the root through a sequence of
// configured relationships. An empty Via is a field of the root itself.
type FieldPath struct {
	// Field is "entity.field", by configured names.
	Field string   `json:"field"`
	Via   []string `json:"via,omitempty"`
}

// Split returns the entity and field names.
func (f FieldPath) Split() (entity, field string, ok bool) {
	return splitField(f.Field)
}

func (f FieldPath) String() string { return describePath(f.Field, f.Via) }

func splitField(s string) (entity, field string, ok bool) {
	entity, field, ok = strings.Cut(s, ".")
	if !ok || entity == "" || field == "" || strings.Contains(field, ".") {
		return "", "", false
	}
	return entity, field, true
}

func describePath(target string, via []string) string {
	if len(via) == 0 {
		return target
	}
	return target + " via " + strings.Join(via, " → ")
}

// ConditionKind distinguishes the condition shapes.
type ConditionKind string

const (
	// Compare is field <op> value(s).
	Compare ConditionKind = "compare"
	// Range is a date field inside a HALF-OPEN range: start <= field < end.
	// Dates are always resolved before a plan exists; a plan never holds
	// "last month", only the instants it resolved to (Phase 3's decision).
	Range ConditionKind = "range"
	// Exists requires at least one row at the end of Via.
	Exists ConditionKind = "exists"
	// Count compares the number of rows at the end of Via with a whole number.
	Count ConditionKind = "count"
)

// Condition is one restriction on the root rows.
type Condition struct {
	Kind ConditionKind `json:"kind"`
	// Field is "entity.field" for compare and range.
	Field string `json:"field,omitempty"`
	// Via is the path from the root: to the field's entity for compare and
	// range, and the traversed path itself for exists and count.
	Via []string `json:"via,omitempty"`
	// Op is the comparison for compare and count.
	Op config.Operator `json:"op,omitempty"`
	// Values: exactly one, except in/nin which take one or more. Count takes
	// one whole number.
	Values []Value `json:"values,omitempty"`
	// Start and End bound a range. Half-open.
	Start *time.Time `json:"start,omitempty"`
	End   *time.Time `json:"end,omitempty"`
	// Negate is NOT for range and exists. A compare's negation is already
	// folded into its operator (gt → lte), which is why compare may not set it.
	Negate bool `json:"negate,omitempty"`
}

// Path is the condition's field path (compare, range).
func (c Condition) Path() FieldPath { return FieldPath{Field: c.Field, Via: c.Via} }

// Aggregate is a function over a field, or COUNT(*) of an entity's rows.
type Aggregate struct {
	Func config.Aggregation `json:"func"`
	// Field is "entity.field"; empty for count of rows.
	Field string `json:"field,omitempty"`
	// Rows names the entity whose rows count(*) counts.
	Rows string   `json:"rows,omitempty"`
	Via  []string `json:"via,omitempty"`
}

func (a Aggregate) String() string {
	if a.Field == "" {
		return fmt.Sprintf("%s(%s)", a.Func, describePath(a.Rows+".*", a.Via))
	}
	return fmt.Sprintf("%s(%s)", a.Func, describePath(a.Field, a.Via))
}

// HavingCondition restricts groups: aggregate <op> number.
type HavingCondition struct {
	Aggregate Aggregate       `json:"aggregate"`
	Op        config.Operator `json:"op"`
	Value     Value           `json:"value"`
}

// OrderKey sorts by a field or by one of the plan's aggregates (by index).
type OrderKey struct {
	Field     string   `json:"field,omitempty"`
	Via       []string `json:"via,omitempty"`
	Aggregate *int     `json:"aggregate,omitempty"`
	Desc      bool     `json:"desc,omitempty"`
}

// ValueKind is a value's type.
type ValueKind string

const (
	NumberValue ValueKind = "number"
	StringValue ValueKind = "string"
	BoolValue   ValueKind = "bool"
	TimeValue   ValueKind = "time"
)

// Value is a comparison operand. Exactly one of the typed members is
// meaningful, chosen by Kind.
//
// Its JSON form is a one-key object — {"number": 5}, {"string": "IN"},
// {"bool": true}, {"time": "2025-01-01T00:00:00Z"} — so a hand-written plan
// cannot leave the type implicit.
type Value struct {
	Kind ValueKind
	// Number is exact (decision 022 §2): the digits the sentence wrote reach
	// the parameters unchanged. Its JSON form is a number literal with every
	// digit — {"number": 99999999999999999999999} — never a float's nearest
	// value, and the zero Decimal is not a number, so a hand-built value
	// without one is refused by the compiler rather than read as 0.
	Number numeric.Decimal
	String qferr.Sensitive
	Bool   bool
	Time   time.Time
}

// Num, Str, Bool and Time build values.
func Num(d numeric.Decimal) Value { return Value{Kind: NumberValue, Number: d} }
func Str(s string) Value          { return Value{Kind: StringValue, String: qferr.Sensitive(s)} }
func Boolean(b bool) Value        { return Value{Kind: BoolValue, Bool: b} }
func Instant(t time.Time) Value   { return Value{Kind: TimeValue, Time: t} }

// Render shows the value; strings only when reveal is set.
func (v Value) Render(reveal bool) string {
	switch v.Kind {
	case NumberValue:
		return v.Number.String()
	case StringValue:
		if reveal {
			return strconv.Quote(v.String.Reveal())
		}
		return qferr.Placeholder
	case BoolValue:
		return strconv.FormatBool(v.Bool)
	case TimeValue:
		return v.Time.Format(time.RFC3339)
	}
	return "?"
}

// UnmarshalJSON reads the one-key form.
func (v *Value) UnmarshalJSON(data []byte) error {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return fmt.Errorf("a value must be an object like {\"number\": 5}")
	}
	if len(raw) != 1 {
		return fmt.Errorf("a value must have exactly one of number, string, bool, time; it has %d keys", len(raw))
	}
	for k, msg := range raw {
		switch ValueKind(k) {
		case NumberValue:
			// Read exactly: the literal's own digits, not the float64 nearest
			// to them ("1e23" is 10^23, and 99999999999999999999999 stays so).
			var d numeric.Decimal
			if err := json.Unmarshal(msg, &d); err != nil {
				return fmt.Errorf("value.number is not a number in range")
			}
			*v = Num(d)
		case StringValue:
			var s string
			if err := json.Unmarshal(msg, &s); err != nil {
				return fmt.Errorf("value.string is not a string")
			}
			*v = Str(s)
		case BoolValue:
			var b bool
			if err := json.Unmarshal(msg, &b); err != nil {
				return fmt.Errorf("value.bool is not a boolean")
			}
			*v = Boolean(b)
		case TimeValue:
			var t time.Time
			if err := json.Unmarshal(msg, &t); err != nil {
				return fmt.Errorf("value.time is not an RFC 3339 instant")
			}
			*v = Instant(t)
		default:
			return fmt.Errorf("unknown value kind %q (known: number, string, bool, time)", k)
		}
	}
	return nil
}

// MarshalJSON writes the one-key form with strings REDACTED. A plan
// marshalled into a log must not carry the values; there is deliberately no
// revealing marshaller.
func (v Value) MarshalJSON() ([]byte, error) {
	var inner any
	switch v.Kind {
	case NumberValue:
		if !v.Number.Valid() {
			return nil, fmt.Errorf("value has no number")
		}
		inner = v.Number
	case StringValue:
		inner = qferr.Placeholder
	case BoolValue:
		inner = v.Bool
	case TimeValue:
		inner = v.Time
	default:
		return nil, fmt.Errorf("value has no kind")
	}
	return json.Marshal(map[string]any{string(v.Kind): inner})
}

// GoString covers %#v, which would otherwise print the Sensitive field's
// underlying string.
func (v Value) GoString() string { return "plan.Value{" + v.Render(false) + "}" }

// Decode reads a hand-written plan.
//
// STRICT: an unknown key is an error. A plan is the whole meaning of a query,
// and a misspelt key ("filters" for "where") would otherwise drop conditions
// silently — a broader answer than asked, with nothing to show it. That is the
// failure this experiment refuses everywhere else, so it is refused here too.
// Trailing content after the object is refused for the same reason.
func Decode(data []byte) (Plan, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	var p Plan
	if err := dec.Decode(&p); err != nil {
		return Plan{}, qferr.Wrap(qferr.CodeInvalidInput, err, "the plan is not valid plan JSON")
	}
	if dec.More() {
		return Plan{}, qferr.New(qferr.CodeInvalidInput, "the plan file has content after the plan object")
	}
	return p, nil
}

// Explain renders the plan for a person. Structure always; string values only
// when reveal is set.
func (p Plan) Explain(reveal bool) string {
	var s strings.Builder
	fmt.Fprintf(&s, "root: %s\n", p.Root)
	if p.Distinct {
		s.WriteString("distinct\n")
	}
	for _, f := range p.Select {
		fmt.Fprintf(&s, "select: %s\n", f)
	}
	for _, a := range p.Aggregates {
		fmt.Fprintf(&s, "aggregate: %s\n", a)
	}
	for i, c := range p.Where {
		join := "where:"
		if i > 0 {
			join = fmt.Sprintf("  %-4s", strings.ToUpper(string(connective(p.WhereJoin))))
		}
		fmt.Fprintf(&s, "%s %s\n", join, c.describe(reveal))
	}
	for i, h := range p.Having {
		join := "having:"
		if i > 0 {
			join = fmt.Sprintf("  %-4s", strings.ToUpper(string(connective(p.HavingJoin))))
		}
		fmt.Fprintf(&s, "%s %s %s %s\n", join, h.Aggregate, h.Op, h.Value.Render(reveal))
	}
	for _, o := range p.OrderBy {
		dir := "asc"
		if o.Desc {
			dir = "desc"
		}
		target := describePath(o.Field, o.Via)
		if o.Aggregate != nil {
			target = fmt.Sprintf("aggregate[%d]", *o.Aggregate)
		}
		fmt.Fprintf(&s, "order by: %s %s\n", target, dir)
	}
	if p.Limit > 0 {
		fmt.Fprintf(&s, "limit: %d\n", p.Limit)
	}
	for _, n := range p.Notes {
		fmt.Fprintf(&s, "note: %s\n", n)
	}
	return s.String()
}

func (c Condition) describe(reveal bool) string {
	not := ""
	if c.Negate {
		not = "NOT "
	}
	switch c.Kind {
	case Range:
		start, end := "?", "?"
		if c.Start != nil {
			start = c.Start.Format(time.RFC3339)
		}
		if c.End != nil {
			end = c.End.Format(time.RFC3339)
		}
		return fmt.Sprintf("%s%s in [%s, %s)", not, c.Path(), start, end)
	case Exists:
		return fmt.Sprintf("%sexists(%s)", not, strings.Join(c.Via, " → "))
	case Count:
		v := "?"
		if len(c.Values) == 1 {
			v = c.Values[0].Render(reveal)
		}
		return fmt.Sprintf("count(%s) %s %s", strings.Join(c.Via, " → "), c.Op, v)
	default:
		vals := make([]string, len(c.Values))
		for i, v := range c.Values {
			vals[i] = v.Render(reveal)
		}
		return fmt.Sprintf("%s %s %s", c.Path(), c.Op, strings.Join(vals, ", "))
	}
}

// String is the redacted explanation, so %v of a Plan cannot leak.
func (p Plan) String() string { return p.Explain(false) }

// GoString covers %#v.
func (p Plan) GoString() string { return "plan.Plan{" + p.Explain(false) + "}" }

func connective(c Connective) Connective {
	if c == "" {
		return And
	}
	return c
}

// Join returns the effective connective: "and" when unset.
func (c Connective) Join() Connective { return connective(c) }
